mapper.select:
SELECT dept_name AS deptName, NVL(SUM(remain_alert), 0) AS remainAlert, NVL(SUM(appointment_alert), 0) AS appointmentAlert, NVL(SUM(early_leave), 0) AS earlyLeave FROM TR_OUTP_ALT_DEPT WHERE stat_date BETWEEN #{startDate} AND #{endDate}
AND dept_name LIKE '%' || #{deptName} || '%'
GROUP BY dept_name ORDER BY remainAlert DESC

SELECT doctor_name AS doctorName, dept_name AS deptName, NVL(SUM(remain_alert), 0) AS remainAlert, NVL(SUM(appointment_alert), 0) AS appointmentAlert, NVL(SUM(early_leave), 0) AS earlyLeave FROM TR_OUTP_ALT_DOC WHERE stat_date BETWEEN #{startDate} AND #{endDate}
AND dept_name LIKE '%' || #{deptName} || '%'
GROUP BY doctor_name, dept_name ORDER BY remainAlert DESC
